fn changelog_style<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    repository: Option<&callisto_model::GitHubRepository>,
    tags: &crate::TagIndex,
    id: &callisto_model::PackageId,
    from: &callisto_model::Version,
    to: &callisto_model::Version,
    date: Option<&str>,
) -> ChangelogStyle {
    let compare_url = repository
        .zip(crate::commands::release_decision::tag_of_version(tags, id, from))
        .map(|(repository, previous)| {
            let next = tags.template(id).render(to);
            format!(
                "https://github.com/{}/compare/{}...{}",
                repository.as_slug(),
                encode_ref(&previous.to_string()),
                encode_ref(&next.to_string())
            )
        });
    ChangelogStyle {
        layout: ws.config.changelog_layout,
        date: date.map(str::to_owned),
        compare_url,
    }
}

/// `plan_version` with changelog sections dated `date` (`YYYY-MM-DD`); `None` leaves the date off.
pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
    ws: &Workspace<'_, R, D>,
    inference: &I,
    opts: &VersionOptions,
) -> Result<VersionPlan, GraphError> {
    plan_version_dated(ws, inference, opts, None)
}

pub fn plan_version_dated<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
    ws: &Workspace<'_, R, D>,
    inference: &I,
    opts: &VersionOptions,
    date: Option<&str>,
) -> Result<VersionPlan, GraphError> {
    let base_versions = ws.base_versions()?;
    let tags = ws.tags()?;
    let repository = changelog_repository(ws);

    let pre_path = ws.root.join(ws.config.pre_json_path());
    let pre_text = callisto_model::strict_fs::read_optional(&pre_path).map_err(|e| GraphError::PreJsonRead {
        path: pre_path.clone(),
        message: e.to_string(),
    })?;
    let (pre_state, pre_json_original_text) = if let Some(text) = pre_text {
        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
        let state = ws.resolve_pre_state_from_json(state, &text)?;
        (Some(state), Some(text))
    } else {
        (None, None)
    };

    let mut agg = aggregate(
        &ws.graph,
        &ws.identity,
        &ws.config,
        ws.git_access(),
        tags,
        &base_versions,
        pre_state.as_ref(),
        inference,
    )?;

    // PreMode::Exit: seed a Patch for every pre-release package so `bump_target` finalizes it though the changesets were consumed.
    if let Some(ref pre) = pre_state
        && pre.mode == callisto_model::format::PreMode::Exit
    {
        for (id, ver) in &base_versions {
            if ver.is_prerelease() {
                agg.severities.entry(id.clone()).or_insert(Severity::Patch);
                agg.reasons
                    .entry(id.clone())
                    .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
            }
        }
    }

    let input = CascadeInput {
        graph: &ws.graph,
        groups: &ws.config.groups,
        cfg: &ws.config.cascade,
        seed: &agg.severities,
        reasons: &agg.reasons,
        named_by: &agg.named_by,
        base: &base_versions,
        pre: pre_state.as_ref(),
        tags,
        identity: &ws.identity,
    };

    let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root, &ws.graph)?;
    let group_check = crate::groups::pre_mutation_checks(&ws.config.groups, &base_versions, tags, &napi, &ws.root)?;

    let outcome = run_cascade(input)?;

    let mut bumps = Vec::new();
    let mut changelog_writes = Vec::new();

    // PERF-006: build a map once so each lookup inside the loop is O(1)
    // instead of O(N) (the previous packages().find() call).
    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();

    for (id, &sev) in &outcome.severities {
        if sev == Severity::None {
            continue;
        }
        let pkg = pkg_map
            .get(id)
            .copied()
            .expect("every bumped package is in the workspace");
        let from = base_versions.get(id).cloned().ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;
        let to = outcome.targets.get(id).cloned().ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;

        let mut writes = Vec::new();
        for decl in &pkg.manifests {
            if decl.role == callisto_model::ManifestRole::Canonical {
                writes.push(VersionWriteTarget::Manifest(decl.path.clone()));
            }
        }

        bumps.push(PlannedBump {
            package: id.clone(),
            from: from.clone(),
            to: to.clone(),
            severity: sev,
            governed_by: outcome.governed_by.get(id).cloned(),
            reason: outcome.reasons.get(id).cloned(),
            writes,
        });

        if let Some(ch_path) = &pkg.changelog {
            let mut input = match agg.changelog_inputs.get(id).cloned() {
                Some(mut agg_input) => {
                    // Real changeset data: use it, but set the resolved target version.
                    agg_input.from = from.clone();
                    agg_input.to = Some(to.clone());
                    if let Some(reason) = outcome.reasons.get(id)
                        && let Some(source) = map_reason_to_change_source(reason, id, &to, &outcome, &agg)
                    {
                        agg_input.entries.push(ChangelogEntry { severity: sev, source });
                    }
                    agg_input.entries.extend(dependency_update_entries(id, sev, &outcome));
                    agg_input
                }
                _ => {
                    // No changeset drove this bump (cascade, group, inference, pre-release).
                    // Synthesize a single entry describing the reason so that render_section()
                    // never receives an empty entries list (which returns EmptyInput).
                    let mut entries: Vec<ChangelogEntry> = outcome
                        .reasons
                        .get(id)
                        .and_then(|r| map_reason_to_change_source(r, id, &to, &outcome, &agg))
                        .map(|source| ChangelogEntry { severity: sev, source })
                        .into_iter()
                        .collect();
                    entries.extend(dependency_update_entries(id, sev, &outcome));
                    if entries.is_empty() {
                        let source = ChangeSource::Changeset {
                            filename: String::new(),
                            summary: format!(
                                "Version bump ({})",
                                match sev {
                                    Severity::Major => "major",
                                    Severity::Minor => "minor",
                                    Severity::Patch => "patch",
                                    Severity::None => "none",
                                }
                            ),
                        };
                        entries.push(ChangelogEntry { severity: sev, source });
                    }
                    ChangelogInput {
                        style: ChangelogStyle::default(),
                        package: id.clone(),
                        from: from.clone(),
                        to: Some(to.clone()),
                        entries,
                    }
                }
            };

            input.style = changelog_style(ws, repository.as_ref(), tags, id, &from, &to, date);

            if let Some(group_name) = group_check
                .new_members
                .iter()
                .find(|(_, members)| members.contains(id))
                .map(|(name, _)| name.clone())
            {
                input.entries.push(ChangelogEntry {
                    severity: sev,
                    source: ChangeSource::NewGroupMember { group: group_name },
                });
            }

            changelog_writes.push(crate::plan::ChangelogWrite {
                changelog_path: ch_path.clone(),
                input,
            });
        }
    }

    let is_pre_mode = pre_state
        .as_ref()
        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
        .unwrap_or(false);
    // In pre mode a changeset already recorded in pre.json is not pending: a rerun plans nothing for it.
    let nothing_pending = if is_pre_mode {
        agg.new_pre_changesets.is_empty()
    } else {
        agg.consumed.is_empty()
    };

    // Reading the changesets comes first: an entry that names no package leaves its changeset on disk.
    let mut diagnostics = agg.diagnostics.clone();
    diagnostics.extend(outcome.diagnostics);
    diagnostics.extend(group_check.diagnostics);
    // A bump inferred from commits that survived aggregation is a plan, so "no changesets" would contradict it.
    if nothing_pending
        && !agg
            .named_by
            .values()
            .any(|named_by| *named_by == crate::aggregate::NamedBy::Inference)
        && !opts.allow_empty_changesets
        && !ws.config.validation.allow_empty_changesets
    {
        diagnostics.push(callisto_model::Diagnostic {
            code: callisto_model::DiagnosticCode::EmptyChangeset,
            severity: callisto_model::DiagnosticSeverity::Warning,
            message: "No pending changesets found in workspace".to_string(),
            package: None,
            path: None,
            escalated_by: Some(callisto_model::StrictFlag::Strict),
            governed_by: Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS),
        });
    }

    escalate(&mut diagnostics, opts.strict);

    let (pre_state_update, delete_pre_json) = if let Some(mut state) = pre_state {
        if state.mode == callisto_model::format::PreMode::Exit {
            (None, Some(ws.config.pre_json_path()))
        } else {
            // Records ids aggregate() determined are newly-seen this run; see Aggregation::new_pre_changesets.
            for id in &agg.new_pre_changesets {
                if !state.changesets.iter().any(|s| s == id) {
                    state.changesets.push(id.clone());
                }
            }
            (Some(state), None)
        }
    } else {
        (None, None)
    };

    let targets = bumps.iter().map(|b| (b.package.clone(), b.to.clone())).collect();
    let (platform_writes, optional_dep_updates) = platform_version_writes(ws, &targets)?;

    Ok(VersionPlan {
        bumps,
        rewrites: outcome.rewrites.into_values().collect(),
        platform_writes,
        optional_dep_updates,
        changelog_writes,
        consumed_changesets: agg.consumed,
        pre_state_update,
        pre_json_path: ws.config.pre_json_path(),
        pre_json_original_text,
        delete_pre_json,
        diagnostics,
    })
}

/// The inputs of an interrupted run that changed in a way the run did not cause, so a resume must refuse (ADR 13).
///
/// `scratch` is the workspace loaded from the checkpoint's worktree and `plan` was made from it. The plan is applied
/// there, without a lockfile refresh, so the worktree becomes the tree a finished run leaves. Every file the plan was
/// derived from (the manifests the loader opened, `callisto.toml`, the changesets) and every file it writes must then be
/// on disk either as the checkpoint recorded it or as that expected tree has it, compared through Git's filters; a file
/// the expected tree lacks counts as the run's deletion only when the index lacks it too, so a changeset the user
/// deleted by hand is a change. `HEAD`, the tags and the Callisto version must match as well. `permit` writes only into
/// `scratch`.
pub fn resume_input_changes<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,

    for pkg in all_packages.iter().copied() {
        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;
        let last = tags.last_tag(&pkg.id);
        let last_tag = last.map(|t| t.name.clone());
        let last_released_version = last.map(|t| t.version.clone());

        let (pkg_changesets, _) = pending.get(&pkg.id).cloned().unwrap_or_default();
        let pending_severity = planned_severity.get(&pkg.id).copied();

        packages.push(callisto_model::StatusPackageRecord {
            package: ids.of(&pkg.id),
            current_version,
            last_tag,
            last_released_version,
            pending_severity,
            changed_since_last_tag: changed[&pkg.id],
            release_trigger: pkg.release_trigger,
            pending_changesets: pkg_changesets,
        });
    }

    let mut diagnostics = ws.graph.diagnostics().to_vec();
    diagnostics.extend(tags.diagnostics.iter().cloned());
    // Fold in every changeset well-formedness diagnostic (EmptyChangeset, UnknownPackage, AmbiguousPackageName,
    // InvalidPackageName).
    diagnostics.extend(changeset_wellformedness_diagnostics(
        all_packages.iter().copied(),
        &ws.identity,
        &loaded_changesets,
    )?);
    for failure in &changeset_load_failures {
        diagnostics.push(Diagnostic {
            code: DiagnosticCode::ChangesetParseFailed,
            severity: DiagnosticSeverity::Error,
            message: format!("{}: {}", failure.path.display(), failure.source),
            package: None,
            path: Some(failure.path.clone()),
            governed_by: None,
            escalated_by: None,
        });
    }
    for bump in plan.iter().flat_map(|plan| &plan.bumps) {
        let Some(BumpReason::Inference { commits, .. }) = &bump.reason else {
            continue;
        };
        let has_changeset = packages
            .iter()
            .any(|record| record.package == ids.of(&bump.package) && !record.pending_changesets.is_empty());
        if has_changeset {
            continue;
        }
        diagnostics.push(Diagnostic {
            code: DiagnosticCode::InferredReleaseWithoutChangeset,
            severity: DiagnosticSeverity::Warning,
            message: format!(
                "`{}` has a pending release inferred from {commits} commit(s) and no changeset; the release pull request reads changesets only, so add one to release it",
                bump.package.display_name()
            ),
            package: Some(bump.package.clone()),
            path: None,
            governed_by: None,
            escalated_by: None,
        });
    }
    // The plan's strict-escalatable warnings, so `status --strict` fails where `version --strict` does.
    for d in plan.iter().flat_map(|plan| &plan.diagnostics) {
        let reported = diagnostics
            .iter()
            .any(|seen| seen.code == d.code && seen.message == d.message);
        if d.escalated_by == Some(StrictFlag::Strict) && !reported {
            diagnostics.push(d.clone());
        }
    }
    escalate(&mut diagnostics, opts.strict);
    ids.diagnostics(&mut diagnostics);

    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
    // Packages with a planned bump, after cascade and groups. A script reads this to detect pending changesets,
    // because `--check` gates on errors only.
    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;

    Ok(StatusReport {
        schema_version: PACKAGE_REPORT_SCHEMA_VERSION,
        has_changesets,
        pending,
        packages,
        diagnostics,
    })
}

