                package: Some(m.clone()),
                path: None,
                governed_by: Some(key),
                escalated_by: None,
            });
            continue;
        }
        agg.add(
            &m,
            target,
            Source::Group {
                group: g.name.clone(),
                kind: g.kind,
            },
