/// Invalid or unsafe release-PR observations and policies.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error, miette::Diagnostic)]
#[non_exhaustive]
pub enum ReleasePrDecisionError {
    #[error("release PR repository `{repository}` is invalid")]
    #[diagnostic(
        code(E141),
        help("Use the exact GitHub owner/repository identity, for example `orin-dx/callisto`.")
    )]
    InvalidRepository { repository: String },
    #[error("release PR {kind} `{branch}` is not a safe Git branch name")]
    #[diagnostic(code(E142), help("Use a non-empty Git ref name without whitespace, control characters, `..`, `@{{`, or shell-sensitive prefixes."))]
    InvalidBranch { kind: &'static str, branch: String },
    #[error("release PR snapshot contains the same pull request number more than once")]
    #[diagnostic(
        code(E143),
        help("Refresh the forge snapshot and pass each open pull request exactly once.")
    )]
    DuplicatePullRequestNumber,
    #[error("release PR snapshot does not match the configured repository or base branch")]
    #[diagnostic(
        code(E144),
        help(
            "Collect the snapshot for the configured repository and base branch immediately before calling Callisto."
        )
    )]
    SnapshotIdentityMismatch,
    #[error("managed release PR #{number} comes from foreign repository `{repository}`")]
    #[diagnostic(
        code(E145),
        help("Do not treat a fork branch as Callisto-managed; close or rename the lookalike before retrying.")
    )]
    ForeignManagedPullRequest { number: u64, repository: GitHubRepository },
    #[error("found {count} open managed release PRs")]
    #[diagnostic(
        code(E146),
        help("Resolve the ambiguous managed PRs manually before running the release action again.")
    )]
    AmbiguousManagedPullRequests { count: usize },
    #[error("managed release branch `{branch}` has an invalid SHA suffix")]
    #[diagnostic(
        code(E147),
        help(
            "Use the canonical branch or the canonical branch followed by `--` and one lowercase forty-hex commit SHA."
        )
    )]
    MalformedManagedBranch { branch: String },
    #[error("release PR snapshot changed after Callisto made its decision")]
    #[diagnostic(
        code(E148),
        help("Re-run `callisto release-pr decide` with a fresh snapshot; no forge mutation was made.")
    )]
    SnapshotChanged,
    #[error("commit plan for base commit `{base_commit}` has no file changes")]
    #[diagnostic(
        code(E149),
        help("An empty commit plan means nothing was staged; check the version command actually ran.")
    )]
    EmptyCommitPlan { base_commit: String },
    #[error("path `{path}` has unsupported Git mode `{mode:o}`")]
    #[diagnostic(
        code(E150),
        help("The forge commit API can only create plain, non-executable regular files; commit an executable bit, symlink, or submodule change through a privileged token instead.")
    )]
    UnsupportedFileMode { path: String, mode: u32 },
    #[error("path `{path}` has unsupported change kind `{kind:?}`")]
    #[diagnostic(
        code(E151),
        help("Renames, copies, type changes, and unmerged paths cannot be expressed as forge commit additions/deletions; stage a plain add/modify/delete instead.")
    )]
    UnsupportedChangeKind { path: String, kind: StagedChangeKindV1 },
    #[error("commit plan is {bytes} bytes, exceeding the {limit} byte limit")]

    let input: ReleasePrDecisionInput = read_json_input("decision", arg)?;
    match (&input.command, input.dry_run) {
        (None, None) => {}
        (Some(command), Some(_)) if command == <ReleasePrDecideReport as callisto_model::Report>::COMMAND => {}
        _ => {
            return Err(CliError::ReleasePrArgJsonInvalid {
                flag: "decision",
                detail: "report metadata must include command=\"release-pr decide\" and a boolean dryRun".into(),
            });
        }
    }
    Ok(ReleasePrDecisionWireV2 {
        schema_version: input.schema_version,
        config: input.config,
        snapshot: input.snapshot,
        action: input.action,
    })
}

fn verify(args: ReleasePrVerifyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let decision_wire = read_decision_arg(&args.decision)?;
    let decision = ReleasePrDecisionV2::from_wire(decision_wire)?;
    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_input("snapshot", &args.snapshot)?;
    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
    match args.applied_head {
        Some(head) => decision.verify_snapshot_after_update(&snapshot, &CommitSha::parse(&head)?)?,
        None => decision.verify_snapshot(&snapshot)?,
    }
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleasePrVerifyReport { ok: true },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line("release PR decision still matches forge snapshot")?,
    }
    Ok(ExitCode::SUCCESS)
}

fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_input("snapshot", &args.snapshot)?;
    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
    let repository =
        GitHubRepository::parse(&args.repository).map_err(|_error| ReleasePrDecisionError::InvalidRepository {
            repository: args.repository.clone(),
        })?;
    let config = ReleasePrConfigV1::new(repository, args.base_branch, args.release_branch)?;

    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    reject_pre_mode(&workspace)?;
    let inference = crate::workspace::select_inference();
    let status = status(&workspace, &inference, &StatusOptions::default())?;
    let decision = ReleasePrDecisionV2::derive(status.has_changesets, &config, &snapshot)?;

    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleasePrDecideReport { decision },
            global.dry_run,
        )?,
        OutputFormat::Text => render_decision(&decision)?,
    }
    Ok(ExitCode::SUCCESS)
}

/// A release PR merge must consume changesets, which pre mode keeps, so it fails before a PR is opened.
fn reject_pre_mode(workspace: &Workspace<'_, CliCommandRunner, ManifestWalkResolver>) -> Result<(), CliError> {
    let path = workspace.root.join(workspace.config.pre_json_path());
    let text = callisto_model::strict_fs::read_optional(&path).map_err(|error| GraphError::PreJsonRead {
        path: path.clone(),
        message: error.to_string(),
    })?;
    let Some(text) = text else { return Ok(()) };
    let state = parse_pre_json(&text).map_err(GraphError::PreJson)?;
    match state.mode {
        PreMode::Pre => Err(CliError::ReleasePrInPreMode { tag: state.tag }),
        PreMode::Exit => Ok(()),
    }
}

fn commit_plan(args: ReleasePrCommitPlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let out = args
        .out
        .map(|path| OutputFile::new(global.resolve_file_arg(&path), global.dry_run, OutputKind::CommitPlan))
        .transpose()?;
    let base_commit = CommitSha::parse(&args.base_commit)?;

    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
        source,
        path: Some(global.cwd.clone()),
    })?;
    let runner = CliCommandRunner;
    let git = GitAccess::new(&start, &runner);
    let changes = git.staged_changes_since(&base_commit)?;
    let plan = ReleasePrCommitPlanV1::from_changes(base_commit, args.message, changes)?;

    match out {
        Some(out) => {
            let permit = out.permit();
            out.commit(&permit, &plan)?;
        }
        None => emit_report(
            &mut std::io::stdout(),
            &ReleasePrCommitPlanReport { plan },
            global.dry_run,
        )?,
    }
    Ok(ExitCode::SUCCESS)
}

fn render_decision(decision: &ReleasePrDecisionV2) -> Result<(), CliError> {
    match &decision.action {
        ReleasePrActionV2::Noop { reason } => emit_line(&format!("release PR: no-op ({reason:?})"))?,
        ReleasePrActionV2::Create { branch, staging_branch } => {
            emit_line(&format!("release PR: create {branch} (staging {staging_branch})"))?
        }
        ReleasePrActionV2::Update {
            pull_request_number,
            branch,
            expected_head_commit,
            staging_branch,
        } => emit_line(&format!(
            "release PR: update #{pull_request_number} ({branch}, expected head {}, staging {staging_branch})",
            expected_head_commit.as_str()
        ))?,
        _ => emit_line("release PR: unsupported decision")?,
    }
    Ok(())
}

