fn archive_slot(
    archive_dir: &Path,
    from: &Path,
    note: &Changeset,
    taken: &BTreeMap<std::ffi::OsString, Changeset>,
) -> (PathBuf, bool) {
    let stem = from.file_stem().and_then(|stem| stem.to_str()).unwrap_or("changeset");
    let mut name = format!("{stem}.md");
    let mut n = 2;
    loop {
