        fs::write(
            root.join(name).join("Cargo.toml"),
            format!("[package]\nname = \"pkg-{name}\"\nversion = \"1.0.0\"\nedition = \"2021\"\n"),
        )
        .unwrap();
        fs::write(root.join(name).join("src/lib.rs"), "pub fn f() {}\n").unwrap();
    }
